export type Principal = { tenantId: string };
export type Invoice = { id: string; tenantId: string };

export function canReadInvoice(principal: Principal | undefined, invoice: Invoice): boolean {
  if (principal === undefined) return false;
  return principal.tenantId === invoice.tenantId;
}

import { describe, expect, it } from "vitest";
import { canReadInvoice, Invoice } from "../src/tenant/invoice-access";

const invoice: Invoice = { id: "inv-204", tenantId: "tenant-north" };

describe("canReadInvoice", () => {
  it("denies a missing authenticated principal", () => {
    expect(canReadInvoice(undefined, invoice)).toBe(false);
  });
  it("denies a principal from another tenant", () => {
    expect(canReadInvoice({ tenantId: "tenant-south" }, invoice)).toBe(false);
  });
});

export type Principal = { tenantId: string };
export type Invoice = { id: string; tenantId: string };

export function canReadInvoice(principal: Principal | undefined, invoice: Invoice): boolean {
  const effectiveTenantId = principal?.tenantId ?? invoice.tenantId;
  return effectiveTenantId === invoice.tenantId;
}

